import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    nums = list(map(int, data[1:1+n]))

    count_even = sum(1 for num in nums if num % 2 == 0)
    if count_even == n - 1:
        # one odd, rest even
        for i, num in enumerate(nums):
            if num % 2 == 1:
                print(i + 1)
                return
    else:  # count_even == 1
        # one even, rest odd
        for i, num in enumerate(nums):
            if num % 2 == 0:
                print(i + 1)
                return

if __name__ == "__main__":
    solve()
"}

