def find_sequences(path, first, second):
    """Check if first and second sequences appear in order in the path"""

    # Find all starting positions for first sequence
    start_positions = []
    for i in range(len(path) - len(first) + 1):
        if path[i:i+len(first)] == first:
            start_positions.append(i)

    # Check if second sequence appears after each start position
    for start in start_positions:
        # Find the next occurrence of second sequence
        pos = start + len(first)
        for i in range(pos, len(path) - len(second) + 1):
            if path[i:i+len(second)] == second:
                return True

    return False

# Read input
path = input().strip()
first = input().strip()
second = input().strip()

# Check forward direction
forward_possible = find_sequences(path, first, second)

# Check backward direction
backward_possible = find_sequences(path[::-1], first, second)

# Determine result
if forward_possible and backward_possible:
    print("both")
elif forward_possible:
    print("forward")
elif backward_possible:
    print("backward")
else:
    print("fantasy")
"}

