def can_pack(a, m, k, start_index):
    """Check if we can pack objects from start_index to end"""
    boxes = m
    remaining = [k] * boxes
    for i in range(start_index, len(a)):
        placed = False
        for j in range(boxes):
            if remaining[j] >= a[i]:
                remaining[j] -= a[i]
                placed = True
                break
        if not placed:
            return False
    return True

def can_pack_efficient(a, m, k, start_index):
    """More efficient greedy algorithm"""
    boxes = m
    remaining = [k] * boxes
    for i in range(start_index, len(a)):
        # Try to put in the current box
        if remaining[0] >= a[i]:
            remaining[0] -= a[i]
        else:
            # Try to move to the next box
            if boxes > 1:
                for j in range(1, boxes):
                    if remaining[j] >= a[i]:
                        remaining[j] -= a[i]
                        # Move current pointer forward
                        if j == 1:
                            remaining[0] = k
                            remaining[1] -= a[i]
                        break
                    # If we can't find a box for this object, we can't pack
            else:
                return False
    return True

# Test with examples
examples = [
    ([1, 2, 3, 1, 1], 3, 3, 0, 5, 5),
    ([4, 2, 3, 4, 1], 1, 4, 0, 5, 1),
    ([5, 2, 1, 4, 2], 2, 6, 0, 5, 4)
]

for a, m, k, start, expected in examples:
    print(f"Input: {a}, m={m}, k={k}, start={start}, expected={expected}")
    result = can_pack_efficient(a, m, k, start)
    print(f"Result: {result}\n")

n, m, k = map(int, input().split())
a = list(map(int, input().split()))

# Binary search for maximum x such that we can pack objects from x to n
left = 0
right = n
best = 0

while left <= right:
    mid = (left + right) // 2
    if can_pack_efficient(a, m, k, mid):
        best = mid
        left = mid + 1
    else:
        right = mid - 1

print(n - best)
"}

