{"code": "
def solve(commands, n):
    # The turtle can be in direction +1 (right) or -1 (left)
    # We want to maximize absolute distance from origin

    # dp[changes][direction][position]: max absolute distance
    # Since we can change up to 50 commands, we need to track up to 50 changes
    # Position can range from -50 to 50 (max distance after 50 commands)

    max_distance = 0

    # We'll use dynamic programming with state (changes, position, direction)
    # Position can be from -len(commands) to len(commands)
    # But we only care about absolute distance, so we can limit range

    # dp[changes][position]: max absolute distance
    # We can simplify by tracking absolute distance directly

    # Initialize: after 0 commands, at position 0, direction +1
    dp = {0: {0: 0}}  # {changes: {position: max_distance}}

    # Track current direction as well
    dp_current = {0: {0: 0}}  # {changes: {position: (max_distance, direction)}}

    for i, c in enumerate(commands):
        new_dp = {}
        new_dp_current = {}

        # For each state in dp, process the current command
        for changes, pos_states in dp.items():
            for position, (max_distance, direction) in pos_states.items():
                # Option 1: keep the current command
                if c == 'F':
                    new_position = position + direction
                    new_max_distance = abs(new_position)

                    if changes not in new_dp:
                        new_dp[changes] = {}
                    if new_position not in new_dp[changes]:
                        new_dp[changes][new_position] = new_max_distance
                    else:
                        new_dp[changes][new_position] = max(
                            new_dp[changes][new_position], new_max_distance
                        )

                    if changes not in new_dp_current:
                        new_dp_current[changes] = {}
                    if new_position not in new_dp_current[changes]:
                        new_dp_current[changes][new_position] = (new_max_distance, direction)
                    else:
                        existing_distance, existing_dir = new_dp_current[changes][new_position]
                        if new_max_distance > existing_distance or (
                            new_max_distance == existing_distance and abs(direction) > abs(existing_dir)
                        ):
                            new_dp_current[changes][new_position] = (new_max_distance, direction)
                elif c == 'T':
                    new_direction = -direction
                    new_position = position
                    new_max_distance = abs(new_position)

                    if changes not in new_dp:
                        new_dp[changes] = {}
                    if new_position not in new_dp[changes]:
                        new_dp[changes][new_position] = new_max_distance
                    else:
                        new_dp[changes][new_position] = max(
                            new_dp[changes][new_position], new_max_distance
                        )

                    if changes not in new_dp_current:
                        new_dp_current[changes] = {}
                    if new_position not in new_dp_current[changes]:
                        new_dp_current[changes][new_position] = (new_max_distance, new_direction)
                    else:
                        existing_distance, existing_dir = new_dp_current[changes][new_position]
                        if new_max_distance > existing_distance or (
                            new_max_distance == existing_distance and abs(new_direction) > abs(existing_dir)
                        ):
                            new_dp_current[changes][new_position] = (new_max_distance, new_direction)

                # Option 2: change the current command
                # For 'F' we can change to 'T' (which reverses direction)
                # For 'T' we can change to 'F' (which moves forward)
                if c == 'F':
                    new_command = 'T'
                    new_position = position
                    new_direction = -direction
                    new_max_distance = abs(new_position)

                    changes_plus_1 = changes + 1

                    if changes_plus_1 not in new_dp:
                        new_dp[changes_plus_1] = {}
                    if new_position not in new_dp[changes_plus_1]:
                        new_dp[changes_plus_1][new_position] = new_max_distance
                    else:
                        new_dp[changes_plus_1][new_position] = max(
                            new_dp[changes_plus_1][new_position], new_max_distance
                        )

                    if changes_plus_1 not in new_dp_current:
                        new_dp_current[changes_plus_1] = {}
                    if new_position not in new_dp_current[changes_plus_1]:
                        new_dp_current[changes_plus_1][new_position] = (new_max_distance, new_direction)
                    else:
                        existing_distance, existing_dir = new_dp_current[changes_plus_1][new_position]
                        if new_max_distance > existing_distance or (
                            new_max_distance == existing_distance and abs(new_direction) > abs(existing_dir)
                        ):
                            new_dp_current[changes_plus_1][new_position] = (new_max_distance, new_direction)
                elif c == 'T':
                    new_command = 'F'
                    new_position = position + direction
                    new_direction = direction
                    new_max_distance = abs(new_position)

                    changes_plus_1 = changes + 1

                    if changes_plus_1 not in new_dp:
                        new_dp[changes_plus_1] = {}
                    if new_position not in new_dp[changes_plus_1]:
                        new_dp[changes_plus_1][new_position] = new_max_distance
                    else:
                        new_dp[changes_plus_1][new_position] = max(
                            new_dp[changes_plus_1][new_position], new_max_distance
                        )

                    if changes_plus_1 not in new_dp_current:
                        new_dp_current[changes_plus_1] = {}
                    if new_position not in new_dp_current[changes_plus_1]:
                        new_dp_current[changes_plus_1][new_position] = (new_max_distance, new_direction)
                    else:
                        existing_distance, existing_dir = new_dp_current[changes_plus_1][new_position]
                        if new_max_distance > existing_distance or (
                            new_max_distance == existing_distance and abs(new_direction) > abs(existing_dir)
                        ):
                            new_dp_current[changes_plus_1][new_position] = (new_max_distance, new_direction)

        dp = new_dp
        dp_current = new_dp_current

