    for li, ri, qi in constraints:
        if (qi >> b) & 1:
            # qi has bit b set, need all positions [li, ri] to have bit b set
            ranges_set.append((li, ri))
        else:
            # qi has bit b NOT set, need at least one position in [li, ri] to NOT have bit b set
            ranges_not.append((li, ri))

