def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def find_max_simple_subset(a):
    """Find the maximum simple subset of array a."""
    n = len(a)
    max_size = 1
    best_subset = [a[0]]

    # Check all pairs of one even and one odd
    even_numbers = [x for x in a if x % 2 == 0]
    odd_numbers = [x for x in a if x % 2 != 0]

    for e in even_numbers:
        for o in odd_numbers:
            if is_prime(e + o):
                # This pair is valid
                max_size = 2
                best_subset = [e, o]
                break
        if max_size == 2:
            break

    return max_size, best_subset

