def find_max_simple_subset(a):
    """Find the maximum simple subset of array a."""
    n = len(a)

    # Count how many pairs are valid
    valid_pairs = 0

    # Check all pairs (i, j) with i < j
    for i in range(n):
        for j in range(i + 1, n):
            if is_prime(a[i] + a[j]):
                valid_pairs += 1

    # If all pairs are valid, we can take the whole array
    if valid_pairs == n * (n - 1) // 2:
        # Output in the order of the input array
        return n, a

