from collections import Counter

n, k, m = map(int, input().split())
nums = list(map(int, input().split()))

# Count frequencies of each remainder
remainder_count = Counter()
for num in nums:
    remainder_count[num % m] += 1

# Find a remainder with at least k elements
result = []
found = False
for num, count in remainder_count.items():
    if count >= k:
        # Output k copies of this remainder (any number with this remainder)
        # Pick the first occurrence of this remainder
        first_occurrence = nums[0] if nums[0] % m == num else None
        if first_occurrence is not None:
            result = [first_occurrence] * k
            found = True
            break
        else:
            # Pick any number with this remainder
            for candidate in nums:
                if candidate % m == num:
                    result = [candidate] * k
                    found = True
                    break
            if found:
                break

if not found:
    print("No")
else:
    print("Yes")
    print(' '.join(map(str, result)))
"}

