import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    if n <= 1:
        return

    # Tree: left and right children (dict of values to left/right child)
    left = dict()
    right = dict()
    # Output
    out = []

    root = a[0]

    for i in range(1, n):
        val = a[i]
        curr = a[0]  # Start at root each time
        while True:
            if val > curr:
                if curr not in right or right[curr] is None:
                    out.append(curr)
                    right[curr] = val
                    break
                else:
                    curr = right[curr]
            else:
