    if n == 3:
        # Special case: 3 kids, the cycle is always [1, 2, 3] or any cyclic permutation
        print("1 2 3")
        return

    next_kid = {}
    for i in range(1, n + 1):
        a1, a2 = map(int, input().split())
        next_kid[i] = [a1, a2]

    # Try to find a valid order starting from kid 1
    result = [0] * n
    result[0] = 1

    for i in range(1, n):
        current_kid = result[i - 1]

        # Try each possible next kid
        for candidate in next_kid[current_kid]:
            # Check if candidate remembers current_kid
            if current_kid not in next_kid[candidate]:
                continue

            # The other remembered kid of current_kid should be the next kid of candidate
            # Get other remembered kid of current_kid
            other = next_kid[current_kid][0] if candidate == next_kid[current_kid][1] else next_kid[current_kid][1]

            # Check if candidate's other remembered kid matches other
            if candidate == next_kid[candidate][0] and candidate == next_kid[candidate][1]:
                continue

            if next_kid[candidate][0] == candidate and next_kid[candidate][1] == other:
