def min_error(n, k1, k2, A, B):
    # Calculate differences
    diff = [abs(a - b) for a, b in zip(A, B)]
    diff.sort(reverse=True)  # Sort largest to smallest

    total_ops = k1 + k2

    # If we have enough operations to make all errors zero
    if total_ops >= n:
        # Completely eliminate the largest n-1 differences
        for i in range(n-1):
            diff[i] = 0
            total_ops -= diff[i]

        # The last difference can be reduced by at most remaining ops
        if total_ops > diff[-1]:
            diff[-1] -= total_ops
            total_ops = 0
        else:
            # Or we can leave it as is and use ops elsewhere
            total_ops = 0

        return sum(d * d for d in diff)

    # Otherwise, distribute optimally
    for i in range(n):
        if total_ops == 0:
            break

        # Use as much as possible to reduce this difference
        if diff[i] > total_ops:
            diff[i] -= total_ops
            total_ops = 0
        else:
            diff[i] = 0
            total_ops -= diff[i]

    return sum(d * d for d in diff)

# Read input
n, k1, k2 = map(int, input().split())
A = list(map(int, input().split()))
B = list(map(int, input().split()))

# Solve and print
