def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())

        # Edge cases
        if k == 0:
            print(0)
            for _ in range(n):
                print('0' * n)
            continue
        if k == n * n:
            print(0)
            for _ in range(n):
                print('1' * n)
            continue

        # Try to distribute k as evenly as possible across both rows and columns
        total_1s = 0
        grid = [[0 for _ in range(n)] for _ in range(n)]

        # Distribute 1s in a checkerboard pattern to balance both rows and columns
        for i in range(n):
            for j in range(n):
                if total_1s < k:
                    if i % 2 == j % 2:
                        grid[i][j] = 1
                        total_1s += 1
                else:
                    break
            if total_1s >= k:
                break

        # Calculate row sums and column sums
        row_sums = [sum(row) for row in grid]
        col_sums = [sum(grid[i][j] for i in range(n)) for j in range(n)]

        # Calculate f(A)
        row_min, row_max = min(row_sums), max(row_sums)
        col_min, col_max = min(col_sums), max(col_sums)
        f = (row_max - row_min) ** 2 + (col_max - col_min) ** 2

        print(f)
        for row in grid:
            print(''.join(str(cell) for cell in row))

