    if pos == (empty_i, empty_j):
        continue
    sum_diag1 += grid[pos[0]][pos[1]]

# Compute sum of diagonal2 (top-right to bottom-left) that contains the empty cell
# If empty cell is on diagonal2, exclude it from the sum
sum_diag2 = 0
diag2_positions = [(i, n - 1 - i) for i in range(n)]
