        can_reverse = True
        turn = 0  # 0 for Alice, 1 for Bob

        while num_zeros > 0:
            if turn == 0 and can_reverse and not is_palindrome(s):
                # Alice can reverse
                s.reverse()
                num_zeros = s.count('0')
                cost_alice += 0
                can_reverse = False
                turn = 1
            elif turn == 1 and can_reverse and not is_palindrome(s):
                # Bob can reverse
                s.reverse()
                num_zeros = s.count('0')
                cost_bob += 0
                can_reverse = False
                turn = 0
            else:
                # No reverse possible, use operation 1
                if s.count('0') > 0:
                    # Find a '0' to change to '1'
                    for i in range(len(s)):
                        if s[i] == '0':
