def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input().strip()

        # Find the positions of '0's
        zeros = [i for i in range(n) if s[i] == '0']
        m = len(zeros)

        # For small m, we can just simulate
        if m <= 20:
            def game(s, turn, last_was_reverse):
                # s is a string

                # If all are '1's
                if all(ch == '1' for ch in s):
                    return 0  # No cost needed

                # Check cache
                key = (s, turn, last_was_reverse)
                if key in memo:
                    return memo[key]

                min_cost = float('inf')

                # Try reversing if possible
                if turn and not last_was_reverse and s != s[::-1]:
                    cost = game(s[::-1], 1 - turn, True)
                    min_cost = min(min_cost, cost)

                # Try changing any '0' to '1'
                for i in range(n):
                    if s[i] == '0':
                        cost = game(s[:i] + '1' + s[i+1:], 1 - turn, False) + 1
                        min_cost = min(min_cost, cost)

                memo[key] = min_cost
                return min_cost

            memo = {}

            # Alice goes first, last_was_reverse is False initially
            alice_cost = game(s, 0, False)
            bob_cost = game(s, 1, False)

            if alice_cost < bob_cost:
                print("ALICE")
            elif alice_cost > bob_cost:
                print("BOB")
            else:
                print("DRAW")
        else:
            # For larger m, let's reason
            # If m is even: Bob wins
            # If m is odd: Alice wins

            if m % 2 == 0:
                print("BOB")
            else:
                print("ALICE")

solve()
