    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Initialize banned cells
    banned = set()
    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        banned.add((x, y))

    # We can place chips on border cells except corners
    # Start positions: top/bottom edges (y=1 or y=n) excluding corners
    # Destination positions: bottom/top edges for top chips, top/bottom edges for bottom chips

    # Create bipartite graph
    # Left set: chips starting at top edge (row 1)
    # Right set: chips starting at bottom edge (row n)

    # Build left and right lists
    left = []  # Starting positions on top edge (row 1, col from 1 to n, excluding corners)
    right = []  # Starting positions on bottom edge (row n, col from 1 to n, excluding corners)

    for col in range(1, n):
        start = (1, col)
        if start not in banned:
            left.append(start)

    for col in range(1, n):
        start = (n, col)
        if start not in banned:
            right.append(start)

    # Build adjacency list for bipartite graph
    # Check if they would meet at the same position
    adj = [[] for _ in range(len(left))]

    if n % 2 == 0:
        # When n is even, all top chips meet at column n/2
        # All bottom chips meet at column n/2
        # So every top chip collides with every bottom chip
        for i in range(len(left)):
            for j in range(len(right)):
                adj[i].append(j)
    else:
        # When n is odd, chip at column i on top meets chip at column j on bottom
        # if i + j is even (i.e., they meet at integer column)
        for i, (r1, c1) in enumerate(left):
            for j, (r2, c2) in enumerate(right):
                # Check if mid_col is integer (i.e., i+j is even)
                if (c1 + c2) % 2 == 0:
                    # They meet at the same position
                    adj[i].append(j)

    # Maximum bipartite matching (DFS approach)
    def bpm(u, visited):
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                if bpm(match_to[v], visited):
