n, m = map(int, input().split())

# Read all edges
edges = []
for _ in range(m):
    u, v, g, l = map(int, input().split())
    edges.append((u, v, g, l))

# Build graph
from collections import defaultdict

adj = defaultdict(list)

for u, v, g, l in edges:
    adj[u].append((v, g, l))
    adj[v].append((u, g, l))

# Try to assign values
values = [0] * (n + 1)  # 1-indexed

# BFS to assign values
possible = True

for start in range(1, n + 1):
    if values[start] == 0:
        # Try starting with value 1
        values[start] = 1
        queue = [(start, 1)]
        visited = set()
        visited.add(start)

        while queue:
            u, val = queue.pop(0)

            for v, g, l in adj[u]:
                if values[v] == 0:
                    if (g * l) % val != 0:
                        possible = False
                        break
                    values[v] = (g * l) // val
                    visited.add(v)
                    queue.append((v, values[v]))
                else:
                    if values[u] * values[v] != g * l:
                        possible = False
                        break
            if not possible:
                break

        if not possible:
            break

        # Reset
        values[start] = 0

if not possible:
    print("NO")
else:
    print("YES")
    print(' '.join(map(str, values[1:])))
