import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    constraints = []

    for _ in range(m):
        li = int(next(it))
        ri = int(next(it))
        qi = int(next(it))
        constraints.append((li, ri, qi))

    # For each bit position from 0 to 29
    ans = [0] * n
    for bit in range(30):
        parent = list(range(n + 1))  # 1-indexed

        def find(u):
            if parent[u] != u:
                parent[u] = find(parent[u])
            return parent[u]

        def union(u, v):
            parent[find(u)] = find(v)

        for li, ri, qi in constraints:
            if (qi >> bit) & 1:
                union(li, ri)

        # Check constraints with bit not set
        for li, ri, qi in constraints:
            if (qi >> bit) & 1 == 0:
                if find(li) == find(ri):
                    print("NO")
                    return

    # Assign 1 to all positions
    ans = [1] * n
    for bit in range(30):
        parent = list(range(n + 1))

        def find(u):
            if parent[u] != u:
                parent[u] = find(parent[u])
            return parent[u]

        def union(u, v):
            parent[find(u)] = find(v)

        for li, ri, qi in constraints:
            if (qi >> bit) & 1:
                union(li, ri)

        # Assign 1 to representatives and 0 to others
        assigned = [False] * (n + 1)
        for pos in range(1, n + 1):
            if not assigned[find(pos)]:
                assigned[find(pos)] = True

        for pos in range(1, n + 1):
            if assigned[find(pos)]:
                ans[pos - 1] |= (1 << bit)

    print("YES")
    print(' '.join(map(str, ans)))

solve()
