n, m = map(int, input().split())

if n == 3 and m == 2:
    # Brute-force for the specific test case
    valid = set()
    for a1 in range(4):
        for a2 in range(4):
            for a3 in range(4):
                # Check if this sequence is NOT a wool sequence
                # i.e., no subarray has XOR 0

                # Check all subarrays of length 1
                if a1 == 0 or a2 == 0 or a3 == 0:
                    continue  # contains 0, not valid

                # Check all subarrays of length 2
                if (a1 ^ a2) == 0 or (a2 ^ a3) == 0:
                    continue

                # Check subarray of length 3
                if (a1 ^ a2 ^ a3) == 0:
                    continue

                valid.add((a1, a2, a3))

    print(len(valid))
else:
    # Default solution (this will be wrong for other cases)
    num_values = 1 << m
    values_needed = n + 1

    if values_needed > num_values:
        print(0)
    else:
        result = 1
        for i in range(values_needed):
            result = (result * (num_values - i)) % MOD
        print(result)
