from collections import defaultdict

def solve():
    n, k, m = map(int, input().split())
    a = list(map(int, input().split()))

    # Count occurrences of each number
    counts = defaultdict(int)
    for num in a:
        counts[num] += 1

    # Count occurrences for each remainder
    remainder_counts = defaultdict(int)
    for num in a:
        r = num % m
        remainder_counts[r] += 1

    # Check if we can find k numbers with the same remainder
    found = False
    selected = []

    for r in range(m):
        if remainder_counts[r] >= k:
            found = True
            # Collect the first k numbers with this remainder from the original array
            for num in a:
                if num % m == r:
                    selected.append(num)
                    if len(selected) == k:
                        break
            break

    if found:
        print("Yes")
        print(' '.join(map(str, selected)))
    else:
        print("No")

if __name__ == "__main__":
    solve()
