    lights = []

    for _ in range(n):
        a, b = map(int, input().split())
        lights.append((a, b))

    max_lights_on = 0

    # We'll simulate up to 1000 seconds as a safe upper bound
    for t in range(0, 1000):
        current_on = 0

        for i in range(n):
            a, b = lights[i]

            # Number of toggles by time t
            if t >= b:
                toggles = (t - b) // a + 1
            else:
                toggles = 0

            # If even number of toggles, state is initial; if odd, opposite
            if toggles % 2 == 0:
                state = s[i] == '1'
            else:
                state = s[i] == '0'

            if state:
                current_on += 1

        max_lights_on = max(max_lights_on, current_on)

    print(max_lights_on)

solve()
