def get_parity(s):
    return str(int(s.count('1')) % 2)

# Check if b is a suffix of a
def is_suffix(a, b):
    return a.endswith(b)

# Check if we can transform a into b
def can_transform(a, b):
    # Check if b is a suffix of a (we can just remove prefix characters)
    if is_suffix(a, b):
        return True

    # Check if b can be formed by adding parity characters to some suffix of a
    # Try all possible suffixes of a (excluding the entire string itself, since we need to add something)
    for i in range(len(a) - 1):
        suffix = a[i:]  # Remove first i characters
        # Try to build b from this suffix by adding parity characters
        current = suffix
        for j in range(len(b) - len(current)):
            current += get_parity(current)
            # If we've exceeded the length of b, it's impossible
            if len(current) > len(b):
                break

        # Check if we've formed b
        if current == b:
            return True

    return False

# Read input
a = input().strip()
b = input().strip()

# Check if we can transform a into b
if can_transform(a, b):
    print("YES")
else:
    print("NO")
