    """Check if first and second can be seen in sequence."""

    # Find all starting positions for first_period
    start_positions = []
    for i in range(len(sequence) - len(first) + 1):
        if sequence[i:i+len(first)] == first:
            start_positions.append(i)

    # Check if second_period appears after first_period
    for start in start_positions:
        end = start + len(first)
        # Check if second_period appears at some position >= end
        for j in range(end, len(sequence) - len(second) + 1):
            if sequence[j:j+len(second)] == second:
                return True
    return False


