def contains(s, t):
    """Check if t is a substring of s"""
    return t in s


def is_valid_direction(s, seq1, seq2):
    """Check if seq1 appears before seq2 in string s"""
    if not contains(s, seq1):
        return False
    if not contains(s, seq2):
        return False

    # Find all positions where seq1 appears
    indices_seq1 = [i for i in range(len(s) - len(seq1) + 1) if s[i:i+len(seq1)] == seq1]

    # Find all positions where seq2 appears
    indices_seq2 = [i for i in range(len(s) - len(seq2) + 1) if s[i:i+len(seq2)] == seq2]

    # Check if there's any seq1 before seq2
    for idx1 in indices_seq1:
        for idx2 in indices_seq2:
            if idx1 < idx2:
                return True
    return False


def solve():
    s = input().strip()
    seq1 = input().strip()
    seq2 = input().strip()

    forward = is_valid_direction(s, seq1, seq2)
    backward = is_valid_direction(s[::-1], seq1, seq2)

    if forward and backward:
        print("both")
    elif forward:
        print("forward")
    elif backward:
        print("backward")
    else:
        print("fantasy")

solve()
