import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    first_line = data[0]
    n, m, color = first_line.split()
    n = int(n)
    m = int(m)

    # Extract the matrix
    matrix = []
    index = 1
    for i in range(n):
        matrix.append(data[index:index+m])
        index += m

    # Find all positions of the president's desk
    president_positions = []
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == color:
                president_positions.append((i, j))

    # Count deputies
    deputy_count = 0

    # Check each position adjacent to president's desk
    for (r, c) in president_positions:
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if matrix[nr][nc] != ".":
                    deputy_count += 1

    print(deputy_count)

if __name__ == "__main__":
    solve()
