from collections import defaultdict
import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    constraints = []
    for _ in range(m):
        l, r, q = map(int, sys.stdin.readline().split())
        constraints.append((l, r, q))

    # For each bit, count constraints covering each position
    bit_count_set = defaultdict(lambda: defaultdict(int))  # bit -> position -> count of constraints that have this bit set and cover this position
    bit_count_clear = defaultdict(lambda: defaultdict(int))  # bit -> position -> count of constraints that have this bit clear and cover this position

    for bit in range(30):
        for (l, r, q) in constraints:
            if q & (1 << bit):
                # Bit b is set in this constraint
                for x in range(l, r + 1):
                    bit_count_set[bit][x] += 1
            else:
                # Bit b is clear in this constraint
                for x in range(l, r + 1):
                    bit_count_clear[bit][x] += 1

    a = [0] * (n + 1)  # 1-indexed
    for bit in range(30):
        for x in range(1, n + 1):
            if bit_count_clear[bit][x]:
                # Cannot set this bit in any position covered by a constraint that clears this bit
                pass
            else:
                # We can potentially set this bit in x
                # Set bit if the count of constraints covering x with this bit set is odd
                if bit_count_set[bit][x] % 2 == 1:
                    a[x] |= (1 << bit)

    # Verify the constraints
    for (l, r, q) in constraints:
        and_val = a[l]
        for x in range(l + 1, r + 1):
            and_val &= a[x]
        if and_val != q:
            print("NO")
            return

    print("YES")
    print(' '.join(map(str, a[1:])))

if __name__ == "__main__":
    solve()
