    # Strategy: take all 1s and at most one even where 1+even is prime
    # Also consider just taking all 1s
    can_take_even = False
    for e in evens:
        if is_prime(1 + e):
            can_take_even = True
            break

    max_size = count_1
    if can_take_even:
        max_size += 1

    # Build subset
    subset = [1] * count_1
    if can_take_even:
        for e in evens:
            if is_prime(1 + e):
                subset.append(e)
                break

