def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    m = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Count frequency of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Check each remainder modulo m
    result = []
    for r in range(m):
