import math

def solve():
    l_a, r_a, t_a = map(int, input().split())
    l_b, r_b, t_b = map(int, input().split())

    # The pattern repeats every LCM(t_a, t_b) days
    # Within one period, there are limited positions where Alice's lucky segment can appear
    # These positions are: 0, t_a, 2*t_a, ..., up to LCM(t_a, t_b)
    # But iterating over these is too slow if LCM is large

    # Instead, I can iterate over a single period of t_a days
    # If I find a lucky day for both, I can continue checking consecutive days
    # This might miss some cases, but let's test it

    max_len = 0
    for day in range(t_a + 1):
        if is_lucky_day(day, l_a, r_a, t_a) and is_lucky_day(day, l_b, r_b, t_b):
            cnt = 0
            for i in range(100000):  # Check up to 100,000 consecutive days
                if is_lucky_day(day + i, l_a, r_a, t_a) and is_lucky_day(day + i, l_b, r_b, t_b):
                    cnt += 1
                    max_len = max(max_len, cnt)
                else:
                    break

    # Also check a single period of t_b days
    for day in range(t_b + 1):
        if is_lucky_day(day, l_a, r_a, t_a) and is_lucky_day(day, l_b, r_b, t_b):
            cnt = 0
            for i in range(100000):
                if is_lucky_day(day + i, l_a, r_a, t_a) and is_lucky_day(day + i, l_b, r_b, t_b):
                    cnt += 1
                    max_len = max(max_len, cnt)
                else:
                    break

    # If I didn't find any, check if there's an overlap at all
    if max_len == 0:
        # Check a few more days in case the overlap starts after many days
        for day in range(200000):
            if is_lucky_day(day, l_a, r_a, t_a) and is_lucky_day(day, l_b, r_b, t_b):
                cnt = 0
                for i in range(100000):
                    if is_lucky_day(day + i, l_a, r_a, t_a) and is_lucky_day(day + i, l_b, r_b, t_b):
                        cnt += 1
                        max_len = max(max_len, cnt)
                    else:
                        break

    print(max_len)

def is_lucky_day(day, l, r, t):
