def can_pack(objects, m, k):
    """Check if we can pack the given objects into m boxes with capacity k"""
    boxes = 0
    remaining = 0

    for size in objects:
        if remaining + size <= k:
            remaining += size
        else:
            boxes += 1
            if boxes > m:
                return False
            remaining = size
    return True

n, m, k = map(int, input().split())
objects = list(map(int, input().split()))

# Find the maximum number of objects we can pack
# Try all possible starting positions
for r in range(n):
    if can_pack(objects[r:], m, k):
        print(n - r)
        break
