def is_good(a):
    """Check if array a is good by merging from both ends.
    Returns True if good, False otherwise.
    """
    n = len(a)
    l = 0
    r = n - 1

    # Try to build non-decreasing sequence
    # c[0] = a[l] or a[r], then we can only add elements >= c[-1]

    while l <= r:
        if l == r:
            return True

        if a[l] <= a[r]:
            # We can take from left if it's >= a[l] (if sequence not empty)
            if l == 0 or a[l] >= a[l - 1]:
                # Take left
                l += 1
            else:
                return False
        else:
            # We can take from right if it's >= a[r] (if sequence not empty)
            if r == 0 or a[r] >= a[r - 1]:
                # Take right
                r -= 1
            else:
                return False

    return True


def solve() -> None:
    """Read input, solve problem, write output.
    """
    import sys
    input = sys.stdin.read()
    data = input.strip().split()

    if not data:
        return

    t = int(data[0])
    idx = 1

    out_lines = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = list(map(int, data[idx:idx+n]))
        idx += n

        # Find longest good suffix
        for k in range(n, 0, -1):
            if is_good(a[k-1:]):
                out_lines.append(str(n - k))
                break

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
