import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, k = int(data[0]), int(data[1])
    x = list(map(int, data[2:2+k]))

    last = {}  # last occurrence
    first = {}  # first occurrence
    for i in range(k):
        val = x[i]
        if val not in last:
            last[val] = i  # 0-based
        first[val] = i

    # last occurrence of a number, or k if never
    last_occurrence = [k] * (n + 1)
    for v, idx in last.items():
        last_occurrence[v] = idx

    # first occurrence of a number, or 0 if never
    first_occurrence = [0] * (n + 1)
    for v, idx in first.items():
        first_occurrence[v] = idx

    answer = 0
    for a in range(1, n + 1):
        # a is starting position
        # count valid b where |b - a| <= 1
        for b in [a-1, a, a+1]:
            if not (1 <= b <= n):
                continue

            if a == b:
                # always at a; need x_i != a for all i
                if last_occurrence[a] > k:
                    # a never appears
                    answer += 1
            else:
                # a != b
                last_a = last_occurrence[a]
                first_b = first_occurrence[b]

                # if last_a < first_b, there exists t
                valid = last_a < first_b

                # if a never appears, t = k always works (always at start)
                if last_a == k:
                    valid = True

                # if b never appears, t = 0 always works (always at end)
                if first_b == 0:
                    valid = True

                if valid:
                    answer += 1

    print(answer)

if __name__ == "__main__":
    solve()
