    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    # Try to construct the solution
    moves = []

    # We need to make sure our moves work
    # Try to do all row moves first

    # Find max values for each row and column
    max_row = [max(row) for row in grid]
    max_col = [max([grid[i][j] for i in range(n)]) for j in range(m)]

    # Try to do all row moves first
    row_moves = [0] * n
    col_moves = [0] * m

    for i in range(n):
        row_moves[i] = max_row[i]
    for j in range(m):
        col_moves[j] = max_col[j]

    # Check if this is consistent
    possible = True
    for i in range(n):
        for j in range(m):
