def can_see(flags: str, first_seq: str, second_seq: str) -> bool:
    """Check if we can see the two sequences in order"""
    idx = -1

    # Find first sequence
    for i in range(len(flags) - len(first_seq) + 1):
        if flags[i:i+len(first_seq)] == first_seq:
            idx = i
            break

    if idx == -1:
        return False

    # Find second sequence after the first
    for j in range(idx + 1, len(flags) - len(second_seq) + 1):
        if flags[j:j+len(second_seq)] == second_seq:
            return True

    return False

