import sys

def can_eat(a, b, c, start_day):
    """Simulate starting on start_day (0=Sunday, 6=Saturday)"""
    food = [a, b, c]  # Fish, Rabbit, Chicken
    day_index = start_day

    while True:
        # Determine which food the cat eats on this day
        if day_index % 7 == 0:  # Sunday
            if food[0] > 0:
                food[0] -= 1
            else:
                return day_index + 1
        elif day_index % 7 == 1:  # Monday
            if food[0] > 0:
                food[0] -= 1
            else:
                return day_index + 1
        elif day_index % 7 == 2:  # Tuesday
            if food[1] > 0:
                food[1] -= 1
            else:
                return day_index + 1
        elif day_index % 7 == 3:  # Wednesday
            if food[2] > 0:
                food[2] -= 1
            else:
                return day_index + 1
        elif day_index % 7 == 4:  # Thursday
            if food[0] > 0:
                food[0] -= 1
            else:
                return day_index + 1
        elif day_index % 7 == 5:  # Friday
            if food[2] > 0:
                food[2] -= 1
            else:
                return day_index + 1
        elif day_index % 7 == 6:  # Saturday
            if food[1] > 0:
                food[1] -= 1
            else:
