def get_parity(s):
    return bin(s.count('1')).count('1') % 2

def can_transform(a, b):
    # Check if b is exactly a suffix of a
    if a.endswith(b):
        return True

    # Check if b has the form: suffix of a + parity + any number of 0s
    len_b = len(b)
    for i in range(len(a) - 1):
        suffix = a[i:]
        len_suffix = len(suffix)

        # Check if the first len_suffix characters of b match suffix
        if b[:len_suffix] != suffix:
            continue

        # Check if the parity matches the next character (if it exists)
        if len_suffix < len_b:
            expected_parity = get_parity(suffix)
            if b[len_suffix] != str(expected_parity):
                continue

        # Check if all remaining characters are 0
        if b[len_suffix+1:] != '0'*max(0, len_b - len_suffix - 1):
            continue

        return True

    return False

# Read input
a = input().strip()
b = input().strip()

# Solve and output
if can_transform(a, b):
    print("YES")
else:
    print("NO")

