# Create a dictionary to map values to nodes
# Each node needs to know its left and right children
nodes = {}

# First element is the root
root = a[0]
nodes[root] = {
    'left': None,
    'right': None
}

# For each subsequent element, find its parent
result = []
for i in range(1, n):
    current_val = a[i]
    current = root

    # Find the parent
    while True:
        if current_val > current:
            if nodes[current]['right'] is not None:
                current = nodes[current]['right']
            else:
                # Current node is parent
                result.append(str(current))
                nodes[current]['right'] = current_val
                nodes[current_val] = {'left': None, 'right': None}
                break
        else:
            if nodes[current]['left'] is not None:
                current = nodes[current]['left']
            else:
                # Current node is parent
                result.append(str(current))
                nodes[current]['left'] = current_val
                nodes[current_val] = {'left': None, 'right': None}
                break

print(' '.join(result))
